      "service": "profile",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, service_name, count(*) n, round(avg(value),2) avg_available, min(time) t0, max(time) t1 FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='profile' GROUP BY 1,2", "claim": "profile deployment availability is 0 across the whole abnormal window, versus 1 in normal."},
        {"kind": "log", "sql": "SELECT regexp_extract(message, 'name\":\"([a-z0-9-]+)', 1) pod, regexp_extract(message, 'note\":\"([^\"]+)', 1) note, min(time) t, count(*) n FROM abnormal_logs WHERE message LIKE '%profile-747d8657db-kpxsd%' GROUP BY 1,2 ORDER BY 3 LIMIT 30", "claim": "profile container definition changed, then failed with OCI runtime create errors and entered back-off restarting."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), round(avg(duration)/1e6,2) FROM normal_traces WHERE span_name='profile.Profile/GetProfiles' GROUP BY 1,2,3,4", "claim": "No profile server spans in abnormal period; frontend's GetProfiles client calls drop from 1427 to 335 and fail in about 0.01 ms."}
      ]
    },
    {
      "service": "recommendation",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "metric", "sql": "SELECT metric, service_name, count(*) n, round(avg(value),2) avg_available, min(time) t0, max(time) t1 FROM abnormal_metrics WHERE metric='k8s.deployment.available' AND service_name='recommendation' GROUP BY 1,2", "claim": "recommendation deployment availability is 0 for the rest of the abnormal window."},
        {"kind": "log", "sql": "SELECT regexp_extract(message, 'name\":\"([a-z0-9-]+)', 1) pod, regexp_extract(message, 'note\":\"([^\"]+)', 1) note, min(time) t, count(*) n FROM abnormal_logs WHERE message LIKE '%recommendation-74d94b6f68-46xlv%' GROUP BY 1,2 ORDER BY 3 LIMIT 30", "claim": "recommendation container was killed for a definition change, then failed to start with OCI runtime errors and back-off."},
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, count(*) n, round(avg(duration)/1e6,2) avg_ms FROM abnormal_traces WHERE span_name='recommendation.Recommendation/GetRecommendations' GROUP BY 1,2,3,4 UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, count(*), round(avg(duration)/1e6,2) FROM normal_traces WHERE span_name='recommendation.Recommendation/GetRecommendations' GROUP BY 1,2,3,4", "claim": "recommendation server spans vanish in abnormal period; frontend's GetRecommendations calls fail near-instantly, 199 calls all erroring on /recommendations."}
      ]
    }
  ],
  "propagation": [
    {"from": "profile", "to": "frontend",
